<script>
(function(){
'use strict';
var d = document;

/* ---------- Year ---------- */
var yearEl = d.getElementById('year');
if(yearEl) yearEl.textContent = String(new Date().getFullYear());

/* ---------- Duplicate ticker for seamless loop ---------- */
var track = d.getElementById('tickerTrack');
if(track){ track.innerHTML += track.innerHTML; }

/* ---------- Scroll: header, progress, back-to-top ---------- */
var header = d.getElementById('siteHeader');
var toTop = d.getElementById('toTop');
var progress = d.getElementById('progress');
function onScroll(){
  var y = window.scrollY || window.pageYOffset || 0;
  if(header) header.classList.toggle('scrolled', y > 50);
  if(toTop) toTop.classList.toggle('show', y > 700);
  if(progress){
    var h = d.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    progress.style.width = (max > 0 ? (y / max) * 100 : 0) + '%';
  }
}
window.addEventListener('scroll', onScroll, {passive:true});
onScroll();
if(toTop) toTop.addEventListener('click', function(){
  window.scrollTo({top:0, behavior:'smooth'});
});

/* ---------- Mobile nav ---------- */
var navToggle = d.getElementById('navToggle');
var nav = d.getElementById('mainNav');
if(navToggle && nav){
  navToggle.addEventListener('click', function(){
    var open = nav.classList.toggle('open');
    navToggle.classList.toggle('active', open);
    navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
  });
  var links = nav.querySelectorAll('a');
  for(var i=0;i<links.length;i++){
    links[i].addEventListener('click', function(){
      nav.classList.remove('open');
      navToggle.classList.remove('active');
      navToggle.setAttribute('aria-expanded','false');
    });
  }
}

/* ---------- Reveal on scroll ---------- */
var reveals = [].slice.call(d.querySelectorAll('.reveal'));
if('IntersectionObserver' in window){
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  }, {threshold:0.12, rootMargin:'0px 0px -40px 0px'});
  reveals.forEach(function(el){ io.observe(el); });
}else{
  reveals.forEach(function(el){ el.classList.add('in'); });
}

/* ---------- Location filters ---------- */
var chips = [].slice.call(d.querySelectorAll('.chip'));
var cards = [].slice.call(d.querySelectorAll('.loc-card'));
chips.forEach(function(c){
  c.addEventListener('click', function(){
    chips.forEach(function(x){ x.classList.remove('active'); });
    c.classList.add('active');
    var f = c.getAttribute('data-filter');
    cards.forEach(function(card){
      var show = (f === 'all') || (card.getAttribute('data-tier') === f);
      card.classList.toggle('hide', !show);
    });
  });
});

/* ---------- Budget estimator ---------- */
var RATES = {
  premium:{ land:[5000,14000], villa:[7000,16000], condo:[2800,8500] },
  mid:    { land:[1500,5500],  villa:[2800,7500],  condo:[1600,4200] },
  value:  { land:[600,2400],   villa:[1300,3800],  condo:[900,2400] }
};
var FX = 57;
var calcTier = d.getElementById('calcTier');
var calcType = d.getElementById('calcType');
var calcSize = d.getElementById('calcSize');
var calcSizeVal = d.getElementById('calcSizeVal');
var calcOut = d.getElementById('calcOut');
function money(n, cur){
  return cur + ' ' + Math.round(n).toLocaleString('en-US');
}
function calc(){
  if(!calcTier || !calcType || !calcSize || !calcOut) return;
  var r = RATES[calcTier.value][calcType.value];
  var s = parseInt(calcSize.value, 10);
  var lo = r[0] * s, hi = r[1] * s;
  if(calcSizeVal) calcSizeVal.textContent = s.toLocaleString('en-US') + ' m²';
  calcOut.innerHTML =
    '<div class="calc-line big">' + money(lo,'$') + ' – ' + money(hi,'$') + '</div>' +
    '<div class="calc-line">' + money(lo*FX,'₱') + ' – ' + money(hi*FX,'₱') + ' <span style="opacity:.65">(at ₱57 / US$1)</span></div>' +
    '<div class="calc-line">With ~10% taxes &amp; fees: <strong>' + money(lo*1.10,'$') + ' – ' + money(hi*1.10,'$') + '</strong></div>' +
    '<p class="calc-note">Indicative 2024–25 ranges for beachfront / near-beach property. Actual prices vary by exact location, title status, lot size and negotiation. For land, minimum lot sizes (often 300–1,000+ m²) usually apply.</p>';
}
if(calcTier){
  calcTier.addEventListener('change', calc);
  calcType.addEventListener('change', calc);
  calcSize.addEventListener('input', calc);
  calc();
}

/* ---------- Checklist ---------- */
var boxes = [].slice.call(d.querySelectorAll('.check-item input'));
var checkBar = d.getElementById('checkBar');
var checkCount = d.getElementById('checkCount');
var checkMsg = d.getElementById('checkMsg');
function updCheck(){
  var total = boxes.length;
  var done = 0;
  boxes.forEach(function(b){ if(b.checked) done++; });
  if(checkBar) checkBar.style.width = (total ? (done/total)*100 : 0) + '%';
  if(checkCount) checkCount.textContent = done + ' of ' + total + ' complete';
  if(checkMsg){
    if(total > 0 && done === total){
      checkMsg.textContent = 'Outstanding — with this file complete, you are ready to negotiate with confidence.';
    }else if(done > total * 0.5){
      checkMsg.textContent = 'Solid progress — keep verifying; nothing moves until the file is whole.';
    }else{
      checkMsg.textContent = 'Work through these before any money moves.';
    }
  }
}
boxes.forEach(function(b){ b.addEventListener('change', updCheck); });
updCheck();
var checkReset = d.getElementById('checkReset');
if(checkReset) checkReset.addEventListener('click', function(){
  boxes.forEach(function(b){ b.checked = false; });
  updCheck();
});

/* ---------- FAQ accordion ---------- */
var faqs = [].slice.call(d.querySelectorAll('.faq-item'));
faqs.forEach(function(item){
  var btn = item.querySelector('.faq-q');
  var panel = item.querySelector('.faq-a');
  btn.addEventListener('click', function(){
    var isOpen = item.classList.contains('open');
    faqs.forEach(function(o){
      o.classList.remove('open');
      o.querySelector('.faq-q').setAttribute('aria-expanded','false');
      var p = o.querySelector('.faq-a');
      if(p) p.style.maxHeight = null;
    });
    if(!isOpen){
      item.classList.add('open');
      btn.setAttribute('aria-expanded','true');
      panel.style.maxHeight = panel.scrollHeight + 'px';
    }
  });
});
window.addEventListener('resize', function(){
  faqs.forEach(function(item){
    if(item.classList.contains('open')){
      var p = item.querySelector('.faq-a');
      if(p) p.style.maxHeight = p.scrollHeight + 'px';
    }
  });
});
})();
</script>
</body>
</html>
"}

